import React from 'react';

// Colour-coded label so a bill raised from an issued inventory item is told apart from a plain
// custom bill at a glance (StudentCustomBillDto.billType: CUSTOM | INVENTORY).
const TYPE_STYLES = {
  INVENTORY: { label: 'Inventory', color: '#1565c0', background: '#e3f2fd' },
  CUSTOM: { label: 'Custom', color: '#6a1b9a', background: '#f3e5f5' },
};

const BillTypeTag = ({ billType }) => {
  const { label, color, background } = TYPE_STYLES[billType] || TYPE_STYLES.CUSTOM;
  return (
    <span
      style={{
        color,
        background,
        fontSize: 11,
        fontWeight: 'bold',
        padding: '2px 8px',
        borderRadius: 4,
        whiteSpace: 'nowrap',
      }}>
      {label}
    </span>
  );
};

export default BillTypeTag;
