import React from 'react';
import { connect } from 'react-redux';
import { Row, Col } from 'reactstrap';
import moment from 'moment';
import CustomButton from 'components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import MuiTable from 'views/admin/Common/MuiTable.jsx';
import BillingFormModal from 'views/admin/Students/components/BillingFormModal.jsx';
import BillTypeTag from 'views/admin/Students/components/BillTypeTag.jsx';
import BillReceiptLinks from 'views/admin/Common/BillReceiptLinks.jsx';
import {
  fetchAllStudentBillingsService,
  addStudentBillingService,
  updateStudentBillingService,
} from 'actions/admin/billing';
import { fetchSchoolStudentsPlainService } from 'actions/admin/students';
import { showToast } from 'actions/admin/auth';
import { formatMoney, getGlobalCurrentBatchUtils } from 'utils/commonFunc';
import { formStudentName, regNoStatic } from 'config/constants';
import { store } from 'index';
import colors from 'config/colors';

const tableHeaders = [
  'Name',
  'Payer',
  regNoStatic,
  'Class',
  'Mobile',
  'Bill Name',
  'Type',
  'Notes',
  'Amount',
  'Due Date',
  'Receipt',
];
const bodyColumns = [
  'payerNameLabel',
  'payerTypeLabel',
  'registerNumber',
  'classLabel',
  'mobileLabel',
  'billName',
  'typeLabel',
  'description',
  'amountLabel',
  'dueDateLabel',
  'receiptLabel',
];

class BillingsPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: null,
      isFetching: false,
      isSaving: false,
      isModalOpen: false,
      editingBill: null,
      searchText: '',
      // Every student of the school's current batch (not just a page) - feeds both the picker in
      // the Add Bill modal and the name/register number lookup for the list rows.
      students: [],
      isStudentsFetching: false,
    };
  }

  componentDidMount() {
    const globalSchool = this.props.loggedUserSchool;
    if (globalSchool) {
      this.setState({ schoolId: globalSchool }, () => {
        this.fetchBillings();
        this.fetchStudents();
      });
    }
  }

  fetchBillings = () => {
    this.setState({ isFetching: true });
    this.props
      .fetchAllStudentBillings({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      })
      .then(() => this.setState({ isFetching: false }));
  };

  fetchStudents = () => {
    const { batchId } = getGlobalCurrentBatchUtils();
    this.setState({ isStudentsFetching: true });
    fetchSchoolStudentsPlainService(this.state.schoolId, batchId, this.props.loggedUserToken)
      .then(data => this.setState({ students: data?.content || [], isStudentsFetching: false }))
      .catch(err => {
        console.error('err-fetchSchoolStudentsPlainService', err);
        this.setState({ isStudentsFetching: false });
      });
  };

  openAddBill = () => this.setState({ isModalOpen: true, editingBill: null });

  closeModal = () => this.setState({ isModalOpen: false, editingBill: null });

  showWarning = (message, type) => store.dispatch(showToast(message, type));

  submitCreateBill = postData => {
    this.setState({ isSaving: true });
    return this.props
      .createBilling({
        ...postData,
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.setState({ isSaving: false });
        this.fetchBillings();
      })
      .catch(err => {
        this.setState({ isSaving: false });
        throw err;
      });
  };

  submitUpdateBill = (studentCustomBillId, postData) => {
    this.setState({ isSaving: true });
    return this.props
      .updateBilling({ ...postData, studentCustomBillId, token: this.props.loggedUserToken })
      .then(() => {
        this.setState({ isSaving: false });
        this.fetchBillings();
      })
      .catch(err => {
        this.setState({ isSaving: false });
        throw err;
      });
  };

  render() {
    const { isFetching, isSaving, isModalOpen, editingBill, searchText, students, isStudentsFetching } = this.state;
    const { allStudentBillings } = this.props;
    const studentOptions = students.map(el => ({
      value: el.studentId,
      label: `${formStudentName(el)}${el.registerNumber ? ` (${el.registerNumber})` : ''}`,
    }));
    // StudentCustomBillDto only carries studentId, not the student's name/reg number - the
    // backend doesn't enrich it, so resolve those against the batch student list already
    // fetched for the picker.
    const studentsById = {};
    students.forEach(s => {
      studentsById[s.studentId] = s;
    });

    const search = searchText.trim().toLowerCase();
    const filteredContent = (allStudentBillings || [])
      .map(item => {
        const isOther = !item.studentId;
        // the backend now sends name / admission no / class; the student list is only a fallback
        const student = !isOther ? studentsById[item.studentId] : null;
        return {
          ...item,
          payerNameLabel: item.payerName || (student ? formStudentName(student) : '--'),
          payerTypeLabel: isOther ? 'Other' : 'Student',
          registerNumber: isOther ? '--' : item.registerNumber || student?.registerNumber || '--',
          classLabel: isOther ? '--' : item.className || '--',
          mobileLabel: isOther ? item.payerPhone || '--' : '--',
          typeLabel: <BillTypeTag billType={item.billType} />,
          description: item.description || '--',
          amountLabel: formatMoney(item.amount),
          dueDateLabel: item.dueDate ? moment(item.dueDate).format('DD MMM, YYYY') : '--',
          receiptLabel: (
            <BillReceiptLinks billId={item.studentCustomBillId} status={item.status} schoolId={this.state.schoolId} />
          ),
        };
      })
      .filter(item =>
        search
          ? [item.payerNameLabel, item.registerNumber, item.mobileLabel].some(v =>
              String(v).toLowerCase().includes(search)
            )
          : true
      );

    return (
      <div className="content">
        <Row className="mb-3">
          <Col sm={6} md={5} lg={4}>
            <CustomInput
              name="searchText"
              placeholder="Search by name, admission no or mobile..."
              value={searchText}
              onChange={(name, value) => this.setState({ searchText: value })}
            />
          </Col>
          <Col sm={6} md={7} lg={8}>
            <CustomButton
              name="+ Add Bill"
              onClick={this.openAddBill}
              style={{ float: 'right', backgroundColor: colors.accent, color: colors.white }}
            />
          </Col>
        </Row>
        <MuiTable
          tableHeaders={tableHeaders}
          tableBodyData={{ content: filteredContent }}
          bodyColumns={bodyColumns}
          idName="studentCustomBillId"
          hidePagination
          isLoading={isFetching}
        />
        <BillingFormModal
          isOpen={isModalOpen}
          onClose={this.closeModal}
          editingBill={editingBill}
          isSaving={isSaving}
          onCreate={this.submitCreateBill}
          onUpdate={this.submitUpdateBill}
          showWarning={this.showWarning}
          showStudentPicker
          studentOptions={studentOptions}
          isStudentsLoading={isStudentsFetching}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserSchool: state.auth.loggedUserSchool,
    allStudentBillings: state.billing?.allStudentBillings,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllStudentBillings: data => dispatch(fetchAllStudentBillingsService(data)),
    createBilling: data => dispatch(addStudentBillingService(data)),
    updateBilling: data => dispatch(updateStudentBillingService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(BillingsPage);
